// Python formatting primitives: CPython repr() and json.dumps() equivalents.

function pyStrRepr(s) {
  // CPython quote selection: single quotes by default; if the string
  // contains a single quote but no double quote, use double quotes.
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (code < 0x20 || code === 0x7f) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else {
      out += ch;
    }
  }
  return out + quote;
}

export function pyRepr(value) {
  if (typeof value === 'string') {
    return pyStrRepr(value);
  }
  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }
  if (typeof value === 'number') {
    return String(value);
  }
  if (Array.isArray(value)) {
    return '[' + value.map(pyRepr).join(', ') + ']';
  }
  if (value !== null && typeof value === 'object') {
    const items = Object.keys(value).map(
      (k) => pyStrRepr(k) + ': ' + pyRepr(value[k])
    );
    return '{' + items.join(', ') + '}';
  }
  return String(value);
}

function jsonStr(s) {
  let out = '"';
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '"') {
      out += '\\"';
    } else if (ch === '\\') {
      out += '\\\\';
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === '\b') {
      out += '\\b';
    } else if (ch === '\f') {
      out += '\\f';
    } else if (code < 0x20) {
      out += '\\u' + code.toString(16).padStart(4, '0');
    } else {
      out += ch;
    }
  }
  return out + '"';
}

export function jsonDumps(value) {
  if (typeof value === 'string') {
    return jsonStr(value);
  }
  if (typeof value === 'boolean') {
    return value ? 'true' : 'false';
  }
  if (typeof value === 'number') {
    return String(value);
  }
  if (Array.isArray(value)) {
    return '[' + value.map(jsonDumps).join(', ') + ']';
  }
  if (value !== null && typeof value === 'object') {
    const items = Object.keys(value).map(
      (k) => jsonStr(k) + ': ' + jsonDumps(value[k])
    );
    return '{' + items.join(', ') + '}';
  }
  if (value === null) {
    return 'null';
  }
  return String(value);
}

