// Minimal DeepDiff reimplementation for flat dicts (string keys,
// string|integer values), matching deepdiff's to_dict()-style output.

function pathFor(key) {
  return "root['" + key + "']";
}

export class DeepDiff {
  constructor(t1, t2) {
    this.t1 = t1;
    this.t2 = t2;

    const added = [];
    const removed = [];
    const changedNew = {};

    const keys1 = Object.keys(t1);
    const keys2 = Object.keys(t2);
    const set2 = new Set(keys2);

    for (const k of keys1) {
      if (!set2.has(k)) {
        removed.push(pathFor(k));
      }
    }
    for (const k of keys2) {
      if (!(k in t1)) {
        added.push(pathFor(k));
      } else if (t1[k] !== t2[k]) {
        changedNew[pathFor(k)] = t2[k];
      }
    }

    added.sort();
    removed.sort();

    this.addedPaths = added;
    this.removedPaths = removed;

    this.addedValues = {};
    for (const p of added) {
      // p is root['k']; recover key
      const k = p.slice(6, -2);
      this.addedValues[p] = t2[k];
    }

    this.valuesChangedNew = {};
    const changedPaths = Object.keys(changedNew).sort();
    for (const p of changedPaths) {
      this.valuesChangedNew[p] = changedNew[p];
    }
  }

  toObject() {
    const obj = {};
    if (this.addedPaths.length > 0) {
      obj.dictionary_item_added = this.addedPaths.slice();
    }
    if (this.removedPaths.length > 0) {
      obj.dictionary_item_removed = this.removedPaths.slice();
    }
    const changedPaths = Object.keys(this.valuesChangedNew);
    if (changedPaths.length > 0) {
      const vc = {};
      for (const p of changedPaths) {
        const k = p.slice(6, -2);
        vc[p] = { new_value: this.t2[k], old_value: this.t1[k] };
      }
      obj.values_changed = vc;
    }
    return obj;
  }
}

