// Minimal Delta reimplementation: JSON-style summary of a DeepDiff result.

import { jsonDumps } from './pyformat.mjs';

export class Delta {
  constructor(diff) {
    this.diff = diff;
  }

  toString() {
    const obj = {};
    const added = this.diff.addedValues;
    if (added && Object.keys(added).length > 0) {
      const a = {};
      for (const p of Object.keys(added).sort()) {
        a[p] = added[p];
      }
      obj.dictionary_item_added = a;
    }
    const changed = this.diff.valuesChangedNew;
    if (changed && Object.keys(changed).length > 0) {
      const vc = {};
      for (const p of Object.keys(changed).sort()) {
        vc[p] = { new_value: changed[p] };
      }
      obj.values_changed = vc;
    }
    return '<Delta: ' + jsonDumps(obj) + '>';
  }
}

