14	  return `usage: ${prog} [-h] --a A --b B --c C`;
15	}
16	
17	function printHelp(prog) {
18	  const lines = [
19	    usageLine(prog),
20	    '',
21	    'options:',
22	    '  -h, --help  show this help message and exit',
23	    '  --a A',
24	    '  --b B',
25	    '  --c C',
26	  ];
27	  process.stdout.write(lines.join('\n') + '\n');
28	}
29	
30	function error(prog, msg) {
31	  process.stderr.write(usageLine(prog) + '\n');
32	  process.stderr.write(`${prog}: error: ${msg}\n`);
33	  process.exit(2);
34	}
