36	// Python repr() of a string.
37	function pyRepr(s) {
38	  const hasSingle = s.includes("'");
39	  const hasDouble = s.includes('"');
40	  const quote = hasSingle && !hasDouble ? '"' : "'";
41	  let out = quote;
42	  for (const ch of s) {
43	    if (ch === '\\') out += '\\\\';
44	    else if (ch === quote) out += '\\' + ch;
45	    else if (ch === '\n') out += '\\n';
46	    else if (ch === '\r') out += '\\r';
47	    else if (ch === '\t') out += '\\t';
48	    else out += ch;
49	  }
50	  return out + quote;
51	}
