53	// argparse treats a token as option-like if it starts with '-' and does not
54	// look like a negative number (this parser has no negative-number options).
55	function looksLikeOption(token) {
56	  if (!token.startsWith('-') || token === '-') return false;
57	  if (/^-\d+$|^-\d*\.\d+$/.test(token)) return false; // negative number
58	  return true;
59	}
