61	// Python int(): optional surrounding whitespace, optional +/- sign, digits only.
62	function parseInt_(optName, raw, prog) {
63	  const trimmed = raw.trim();
64	  if (/^[+-]?\d+$/.test(trimmed)) {
65	    return parseInt(trimmed, 10);
66	  }
67	  error(prog, `argument ${optName}: invalid int value: ${pyRepr(raw)}`);
68	}
