70	export function parseArgs(argv, prog) {
71	  const values = {};
72	  const extras = [];
73	
74	  let i = 0;
75	  while (i < argv.length) {
76	    const token = argv[i];
77	
78	    if (token === '-h' || token === '--help') {
79	      printHelp(prog);
80	      process.exit(0);
81	    }
82	
83	    let optName = null;
84	    let inlineValue = null;
85	    if (token.startsWith('--')) {
86	      const eq = token.indexOf('=');
87	      if (eq !== -1) {
88	        optName = token.slice(0, eq);
89	        inlineValue = token.slice(eq + 1);
90	      } else {
91	        optName = token;
92	      }
93	    }
94	
95	    const opt = optName !== null ? OPTIONS.find((o) => o.name === optName) : null;
96	    if (opt) {
97	      let raw;
98	      if (inlineValue !== null) {
99	        raw = inlineValue;
100	      } else {
101	        const next = argv[i + 1];
102	        if (next === undefined || looksLikeOption(next)) {
103	          error(prog, `argument ${opt.name}: expected one argument`);
104	        }
105	        raw = next;
106	        i += 1;
107	      }
108	      values[opt.dest] = opt.type === 'int' ? parseInt_(opt.name, raw, prog) : raw;
109	    } else {
110	      extras.push(token);
111	    }
112	    i += 1;
113	  }
114	
115	  // Required-argument check happens before the unrecognized-argument check.
116	  const missing = OPTIONS.filter((o) => !(o.dest in values)).map((o) => o.name);
117	  if (missing.length > 0) {
118	    error(prog, `the following arguments are required: ${missing.join(', ')}`);
119	  }
120	
121	  if (extras.length > 0) {
122	    error(prog, `unrecognized arguments: ${extras.join(' ')}`);
123	  }
124	
125	  return { a: values.a, b: values.b, c: values.c };
126	}
